// Read-only reproduction against the previously delivered recorder. All files
// generated by this diagnostic are synthetic test media in a temporary folder.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { spawnSync } = require('node:child_process');
const baseline = '/workspace/scratch/d8b5d3d3b0dd/marty-demo-recorder-complete';
const outputRoot = '/workspace/scratch/d8b5d3d3b0dd/runtime-integrity-evidence';
const { assertCaptureQuality, probeMedia } = require(path.join(baseline, 'src/mediaQuality'));
const { normalizeSegmentMap, segmentedVideoFilter, bindOutputRanges } = require(path.join(baseline, 'src/compose'));
const { verifyPointerEvidence } = require(path.join(baseline, 'src/editorialPointer'));
const { resolveTool } = require(path.join(baseline, 'src/preflight'));
const run = (command, args, cwd) => {
  const result = spawnSync(command, args, { cwd, encoding: 'utf8', timeout: 60000, maxBuffer: 4 * 1024 * 1024 });
  assert.equal(result.status, 0, result.error?.message || result.stderr); return result.stdout;
};
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
(async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'marty-media-baseline-'));
  try {
    const native = path.join(root, 'synthetic-native.mp4');
    run(resolveTool('ffmpeg'), ['-v', 'error', '-f', 'lavfi', '-i', 'color=c=blue:s=1080x1920:r=25:d=0.8',
      '-c:v', 'libx264', '-threads', '2', '-preset', 'ultrafast', '-an', native]);
    const nativeMedia = await probeMedia(native);
    let portraitRejection = null;
    try { assertCaptureQuality(nativeMedia); } catch (error) { portraitRejection = error.message; }
    assert(portraitRejection);
    const source = path.join(root, 'synthetic-source.mp4');
    run(resolveTool('ffmpeg'), ['-v', 'error', '-f', 'lavfi', '-i', 'testsrc2=s=320x180:r=25:d=0.8',
      '-c:v', 'libx264', '-threads', '2', '-preset', 'ultrafast', source]);
    const bytes = Buffer.from('{"arbitrary":"hash matching bytes without any source or event"}');
    fs.writeFileSync(path.join(root, 'arbitrary.json'), bytes);
    const pointer = normalizeSegmentMap([{ label: 'Synthetic control', sourceStart: 0, sourceEnd: 0.8, outputDuration: 0.8,
      pointer: { disclosure: 'EDITORIAL_RECONSTRUCTION', timingBasis: 'VISUAL_RESPONSE_BRACKET_OS_CLICK_UNKNOWN',
        events: [{ sourceStart: 0.1, sourceClick: 0.4, sourceEnd: 0.7, from: { x: 80, y: 70 }, target: { x: 150, y: 90 },
          responseBracket: { start: 0.36, end: 0.4 }, controlWindow: { sourceStart: 0, sourceEnd: 0.8, bounds: { x: 100, y: 50, width: 100, height: 80 } },
          evidence: { path: 'arbitrary.json', sha256: hash(bytes), eventId: 'nonexistent-event' } }] } }], 0.8, { width: 320, height: 180 });
    const accepted = verifyPointerEvidence(pointer, source, null, root);
    assert.equal(accepted.length, 1);
    const segments = normalizeSegmentMap(Array.from({ length: 20 }, (_, i) => ({ label: `Fixture ${i}`,
      sourceStart: i / 25, sourceEnd: (i + 1) / 25, outputDuration: 0.26 })), 0.8);
    const encoded = path.join(root, 'synthetic-fractional.mp4');
    run(resolveTool('ffmpeg'), ['-v', 'error', '-i', source, '-filter_complex', segmentedVideoFilter(0, segments),
      '-map', '[segmented]', '-c:v', 'libx264', '-threads', '2', '-preset', 'ultrafast', encoded]);
    const probe = JSON.parse(run(resolveTool('ffprobe'), ['-v', 'error', '-select_streams', 'v:0', '-count_frames',
      '-show_entries', 'stream=duration,nb_read_frames', '-of', 'json', encoded])).streams[0];
    const declaredDuration = bindOutputRanges(segments).at(-1).outputEnd;
    assert(Math.abs(Number(probe.duration) - declaredDuration) > 0.39);
    const record = { kind: 'SYNTHETIC_BASELINE_MEDIA_DIAGNOSTIC', baselineRepository: baseline,
      baselineRevision: run('git', ['rev-parse', 'HEAD'], baseline).trim(),
      unboundPointerDocumentAccepted: true, acceptedNonexistentEventId: accepted[0].eventId,
      actualPortraitCapture: nativeMedia, portraitRejectedByComposerCaptureValidator: portraitRejection,
      fractionalSegments: { count: 20, requestedSecondsEach: 0.26, declaredDurationSeconds: declaredDuration,
        encodedDurationSeconds: Number(probe.duration), encodedFrames: Number(probe.nb_read_frames) },
      qualification: 'NO_PRODUCT_OR_NATIVE_WALLET_EXECUTION' };
    fs.writeFileSync(path.join(outputRoot, 'media-baseline-diagnostics.json'), JSON.stringify(record, null, 2) + '\n');
    process.stdout.write(JSON.stringify(record, null, 2) + '\n');
  } finally { fs.rmSync(root, { recursive: true, force: true }); }
})().catch(error => { console.error(error); process.exitCode = 1; });
